import {bucketSolves,solveEvents} from './dashboard-model.js';
import {escapeHtml as h} from './community-model.js';
export class Dashboard{
 constructor({cloud,getState,getCatalog,getEvents=null,summary=null,name="You"}){Object.assign(this,{cloud,getState,getCatalog,getEvents,summary,name,epoch:0,loadedFor:null});this.$=id=>document.getElementById(id);this.$('graphMonth').value=new Date().toISOString().slice(0,7);this.$('graphYear').value=new Date().getUTCFullYear();for(const id of ['graphMode','graphMonth','graphYear','graphTopic','compareOne','compareTwo'])this.$(id).onchange=()=>this.render();}
 accountChanged(){this.epoch++;this.loadedFor=null;for(const id of ['compareOne','compareTwo'])this.$(id).replaceChildren(new Option('Choose a friend',''));}
 async open(){const owner=this.cloud.user?.id;if(owner&&this.loadedFor!==owner){this.loadedFor=owner;try{const own=await this.cloud.request('self');if(own.profile){const r=await this.cloud.request('following',{target:own.profile.public_id});if(this.cloud.user?.id!==owner)return;for(const id of ['compareOne','compareTwo'])this.$(id).replaceChildren(new Option('Choose a friend',''),...r.users.map(p=>new Option('@'+p.username,p.public_id)));}}catch(e){this.$('dashboardMessage').textContent=e.message;this.loadedFor=null;}}this.render();}
 async render(){const ticket=++this.epoch,$=this.$,catalog=this.getCatalog(),selected=$('graphTopic').value,topics=[...new Set(catalog.map(p=>p.topic))].sort();$('graphTopic').replaceChildren(new Option('All topics',''),...topics.map(t=>new Option(t,t)));if(topics.includes(selected))$('graphTopic').value=selected;const opts={mode:$('graphMode').value,month:$('graphMonth').value,year:Number($('graphYear').value),topic:$('graphTopic').value};$('graphMonth').hidden=opts.mode!=='daily';$('graphYear').hidden=opts.mode==='daily';let own;try{own=bucketSolves(this.getEvents?this.getEvents():solveEvents(this.getState(),catalog),opts);}catch(e){$('dashboardMessage').textContent=e.message;return;}const series=[{name:this.name,data:own,color:'#e23d4b'}];this.draw(series);$('topicBreakdown').innerHTML=own.topics.length?own.topics.map(([t,n])=>'<div class="topic-mini"><span>'+h(t)+'</span><div><i style="width:'+n/Math.max(...own.topics.map(x=>x[1]))*100+'%"></i></div><b>'+n+'</b></div>').join(''):'<p class="muted">Solve a problem to grow your topic chart.</p>';$('dashboardSolved').textContent=this.summary?.solved??Object.keys(this.getState().solved||{}).length;$('dashboardActive').textContent=this.summary?.active??this.getState().days.length;$('dashboardPeriod').textContent=own.total;const ids=[...new Set([$ ('compareOne').value,$('compareTwo').value].filter(Boolean))];$('dashboardMessage').textContent=ids.length?'Loading friend activity…':this.cloud.user?'Compare with up to two people you follow. Their profiles must be discoverable.':'Sign in and follow people to compare activity.';for(const [i,target] of ids.entries()){try{const r=await this.cloud.request('profile',{target});if(ticket!==this.epoch)return;series.push({name:'@'+r.profile.username,data:bucketSolves(r.stats.solves||[],opts),color:['#22aaab','#e79d35'][i]});}catch(e){if(ticket===this.epoch)$('dashboardMessage').textContent=e.message;return;}}if(ticket===this.epoch){this.draw(series);if(ids.length)$('dashboardMessage').textContent='Comparing '+ids.length+' followed explorers.';}}
 draw(series){const $=this.$,keys=series[0].data.keys,w=900,H=225,left=35,top=18,plotH=180,max=Math.max(1,...series.flatMap(s=>s.data.values)),x=i=>left+i*(w-left-12)/Math.max(1,keys.length-1),y=v=>top+plotH-v/max*plotH;let svg='';for(let i=0;i<=4;i++){const v=max*i/4;svg+='<line x1="35" x2="900" y1="'+y(v)+'" y2="'+y(v)+'" class="graph-grid"/><text x="25" y="'+(y(v)+4)+'" text-anchor="end">'+Number(v.toFixed(1))+'</text>';}for(const s of series){svg+='<polyline fill="none" stroke="'+s.color+'" stroke-width="3" points="'+s.data.values.map((v,i)=>x(i)+','+y(v)).join(' ')+'"/>';s.data.values.forEach((v,i)=>{svg+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="4" fill="'+s.color+'"><title>'+h(s.name+' · '+keys[i]+': '+v+' solves')+'</title></circle>';});}keys.forEach((key,i)=>{if(i===0||i===keys.length-1||i%Math.ceil(keys.length/7)===0)svg+='<text x="'+x(i)+'" y="221" text-anchor="middle">'+h(key.length===10?key.slice(-2):key.length===7?key.slice(-2):key)+'</text>';});$('frequencyChart').innerHTML=svg;$('graphLegend').innerHTML=series.map(s=>'<span><i style="background:'+s.color+'"></i>'+h(s.name)+'</span>').join('');$('chartTable').innerHTML='<table><thead><tr><th>Period</th>'+series.map(s=>'<th>'+h(s.name)+'</th>').join('')+'</tr></thead><tbody>'+keys.map((key,i)=>'<tr><th>'+key+'</th>'+series.map(s=>'<td>'+s.data.values[i]+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
}
